<template>
<div class="screen" v-if="data"><header><div class="brand"><span>♨</span><div><h1>天然气智能预测平台</h1><small>Natural Gas Intelligent Prediction Platform</small></div></div><nav><button class="active" @click="selected=''">⌂ 首页</button><button @click="openBuddy('月度销量')">WorkBuddy 智能工作台</button><button @click="selected='事理图谱'">✣ 事理图谱</button><button @click="selected='知识库'">▣ 知识库</button><button @click="selected='任务中心'">▤ 任务中心</button></nav><button title="全屏" @click="fullscreen">⛶</button></header>
<section class="metrics"><article v-for="m in data.metrics" :key="m[1]"><span class="metric-icon">{{m[0]}}</span><div><h3>{{m[1]}}</h3><strong>{{m[2]}} <small>{{m[3]}}</small></strong><em>{{m[4]}}</em></div></article></section>
<main><aside class="left"><section class="panel trend"><h2>历史销量趋势<div class="toggle"><button v-for="period in periods" :key="period.value" :class="{on:granularity===period.value}" @click="granularity=period.value">{{period.label}}</button></div></h2><p class="trend-scope">{{ data.salesScope }}<span>模拟数据</span></p><div ref="bar" class="chart"></div></section><section class="panel industry"><h2>行业用气结构</h2><div class="industry-body"><div ref="donut" class="donut"></div><ul><li v-for="(i,n) in data.industries" :key="i[0]"><i :style="{background:colors[n]}"/>{{i[0]}}<b>{{i[1]}}%</b></li></ul></div></section><section class="panel ranking"><h2>重点省份销量 TOP5 <small>（已接入省份）</small></h2><table><thead><tr><th>排名</th><th>省份</th><th>销量（亿方）</th><th>同比</th></tr></thead><tbody><tr v-for="(p,i) in data.provinces" :key="p[0]"><td><span class="rank">{{i+1}}</span></td><td>{{p[0]}}</td><td>{{p[1]}}</td><td class="green">+{{p[2]}}% ↑</td></tr></tbody></table></section></aside>
<div class="center"><section class="panel map-panel"><div class="map-toolbar"><div class="toggle large"><button :class="{on:!sales}" @click="sales=false">天气分布</button><button :class="{on:sales}" @click="sales=true">销量分布</button></div><span>范围：全部34个省级地区 ⓘ</span></div><TemperatureMap :paused="paused" :sales="sales"/><button class="pause" @click="paused=!paused">{{paused?'▶ 播放热力':'Ⅱ 暂停热力'}}</button></section><section class="buddy"><h2>♙ WorkBuddy · 七大业务智能体</h2><div class="agents"><button v-for="a in data.agents" :key="a[1]" :style="{'--accent':a[4]}" @click="openBuddy(a[1])"><span>{{a[0]}}</span><h3>{{a[1]}}<br>{{a[1]==='天气分析'||a[1]==='销量分析'?'智能体':'预测智能体'}}</h3><p class="agent-features"><span v-for="feature in [...a[2].split('｜'),a[3]]" :key="feature">{{feature}}</span></p></button></div><div class="portals"><button @click="openBuddy('事理分析')"><b>✣　事理分析智能体</b><p>事件关联 ｜ 影响传导 ｜ 归因研判</p></button><button @click="openBuddy('知识问答')"><b>▣　知识问答智能体</b><p>政策查询 ｜ 专业问答 ｜ 资料溯源</p></button></div><div class="platform"></div></section></div>
<aside class="right"><section class="panel insights reasoning"><h2>热点事件影响 <button @click="openBuddy('事理分析')">进入事理分析 ›</button></h2><p class="reason-caption">模拟事件 · 按业务影响排序，非实时新闻</p><button class="reason-row" v-for="r in data.reasoning" :key="r.title" @click="detail={title:r.title,text:r.detail}"><h3>{{r.title}}<small class="event-category">{{r.category}}</small></h3><p class="event-scope">{{r.scope}}</p><div class="reason-chain"><template v-for="(node,i) in r.chain" :key="node"><span v-if="i" class="chain-arrow">→</span><span class="chain-node">{{node}}</span></template></div><p class="reason-purpose">{{r.purpose}}</p></button></section><section class="panel tasks knowledge"><h2>知识库更新 <button @click="openBuddy('知识问答')">进入知识问答 ›</button></h2><button class="knowledge-row" v-for="k in [...data.knowledge].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3)" :key="k.title" @click="detail={title:k.title,text:k.detail}"><span class="knowledge-tag">{{k.category}}</span><div><h3>{{k.title}}</h3><p>{{k.status}} · {{k.updatedAt}}<span class="knowledge-demo">模拟条目</span></p></div><span class="knowledge-chevron">›</span></button></section><section class="panel results"><h2>✣ 近期预测成果 <button @click="selected='预测成果'">查看更多 ›</button></h2><article v-for="r in data.results" :key="r[1]"><span class="round-icon">{{r[0]}}</span><div><h3>{{r[1]}}</h3><p>{{r[2]}}<em>较上期 <b>{{r[3]}}</b></em></p></div></article></section></aside></main><footer><span>天然气智慧能源 · 智能感知 / 精准预测 / 科学决策</span><span>演示数据 · {{clock}}</span></footer><div class="modal" v-if="detail" @click.self="detail=null"><section class="panel"><h2>{{detail.title}}<button @click="detail=null">关闭 ×</button></h2><p>{{detail.text}}</p><p>本地 JSON 演示内容，非实时分析或正式资料。</p></section></div><div class="modal" v-if="selected" @click.self="selected=''"><section class="panel"><h2>{{selected}}<button @click="selected=''">关闭 ×</button></h2><p>当前为纯前端大屏演示，业务数据由本地 JSON 模拟。</p><p>已接入省级地区 34 个 · 已接入客户 320 家 · 模型正常运行</p></section></div></div><div v-else class="loading">{{error||'正在初始化智能预测平台…'}}</div>
</template>
<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick,watch} from 'vue'
import * as echarts from 'echarts'
import TemperatureMap from './TemperatureMap.vue'
const data=ref(),error=ref(''),bar=ref(),donut=ref(),sales=ref(false),paused=ref(false),selected=ref(''),detail=ref(null),granularity=ref('monthly'),range=ref('近7天'),clock=ref('');const periods=[{value:'monthly',label:'月度'},{value:'tenDay',label:'旬度'},{value:'daily',label:'日度'}];const colors=['#139eff','#20e6bc','#ffc63e','#9767ff'];let charts=[],timer,observer
function openBuddy(scene){location.hash='/workbuddy?scene='+encodeURIComponent(scene)}
function fullscreen(){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.()}
function drawBar(){if(!charts[0]||!data.value)return;const rows=data.value.salesSeries[granularity.value];charts[0].setOption({legend:{data:['销量合计','同比增长率'],top:0,textStyle:{color:'#c8e5ff',fontSize:11},itemWidth:13,itemHeight:8},grid:{left:46,right:43,top:46,bottom:28},tooltip:{trigger:'axis',valueFormatter:(value)=>value},xAxis:{type:'category',data:rows.map(row=>row.label),axisLabel:{color:'#d5eaff',fontSize:10},axisLine:{lineStyle:{color:'#285079'}},axisTick:{show:false}},yAxis:[{type:'value',name:'销量（亿方）',nameTextStyle:{color:'#bedbfa'},axisLabel:{color:'#d5eaff',fontSize:10},splitLine:{lineStyle:{color:'#183b61'}}},{type:'value',name:'同比（%）',nameTextStyle:{color:'#bedbfa'},axisLabel:{formatter:'{value}%',color:'#d5eaff',fontSize:10},splitLine:{show:false}}],series:[{name:'销量合计',type:'bar',tooltip:{valueFormatter:v=>v+' 亿方'},data:rows.map(row=>row.volume),barWidth:'48%',itemStyle:{borderRadius:[3,3,0,0],color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#43d6ff'},{offset:1,color:'#0672ca88'}])}},{name:'同比增长率',type:'line',tooltip:{valueFormatter:v=>v+'%'},yAxisIndex:1,data:rows.map(row=>row.growth),smooth:false,symbolSize:6,itemStyle:{color:'#ffe177'},lineStyle:{color:'#ffb637',shadowColor:'#ffb637',shadowBlur:8}}]})}
onMounted(async()=>{try{const r=await fetch('/dashboard.json');if(!r.ok)throw Error();data.value=await r.json();await nextTick();charts=[echarts.init(bar.value),echarts.init(donut.value)];drawBar();charts[1].setOption({color:colors,tooltip:{trigger:'item',formatter:'{b}: {d}%'},title:{text:data.value.totalSales.toFixed(2),subtext:'亿方\n总销量',left:'center',top:'33%',textStyle:{color:'#fff',fontSize:25},subtextStyle:{color:'#b4cfe9',fontSize:11}},series:[{type:'pie',radius:['58%','85%'],center:['50%','50%'],label:{show:false},data:data.value.industryVolumes.map(i=>({name:i.name,value:i.volume}))}]});observer=new ResizeObserver(()=>charts.forEach(c=>c.resize()));observer.observe(bar.value);timer=setInterval(()=>clock.value=new Date().toLocaleString('zh-CN',{hour12:false}),1000)}catch{error.value='演示数据加载失败，请刷新重试'}})
watch(granularity,drawBar);onBeforeUnmount(()=>{charts.forEach(c=>c.dispose());observer?.disconnect();clearInterval(timer)})
</script>
